-- IISER TVM Lecture Hall Complex: Varsha 2026 exam halls (mid-sem and end-sem) for the four lecture halls
-- (Bhaskara, Kaumudi, Jupiter, Venus). Halls in other buildings are not part of this site.
-- Run in the Supabase SQL editor.
--
-- It first DELETES every exam event dated 19-26 Sep 2026 (mid-sem) and 18 Nov - 1 Dec 2026 (end-sem), which
-- removes anything added by the earlier exam scripts, then adds both exam schedules again with plain titles
-- (course codes as printed in the seating plan: codes joined by "/" are ONE course offered to different departments,
-- e.g. "DSC 323/MAT 314/MSM 405"; different courses sharing a hall are separated by a comma, e.g. "HUM 212, I2M 411/MAT 4511").
-- Classes and other events are not touched. Safe to run again.
--   Mid-sem: Sat 19 Sep - Sat 26 Sep, 08:30-10:30, 11:30-13:30, 15:00-17:00.
--   End-sem: Wed 18 Nov - Tue 1 Dec, 09:00-12:00, 14:00-17:00.

begin;

delete from public.events
where event_type = 'exam'
  and (event_date between date '2026-09-19' and date '2026-09-26'
    or event_date between date '2026-11-18' and date '2026-12-01');

insert into public.events (room_id, title, event_type, event_date, start_time, end_time, professor, created_by)
select room_id, title, 'exam', event_date, start_time, end_time, professor, 'admin'
from (values
  ('lhc-bhaskara', 'HUM 312', date '2026-09-19', time '08:30', time '10:30', 'Dr. Piyush Parimoo'),
